data class EncryptedData(val iv: ByteArray, val ciphertext: ByteArray)

fun encrypt(plain: String, key: SecretKey): EncryptedData {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, key)                  // Keystore picks a random IV
    return EncryptedData(cipher.iv, cipher.doFinal(plain.encodeToByteArray()))
}

fun decrypt(data: EncryptedData, key: SecretKey): String {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(128, data.iv))
    return cipher.doFinal(data.ciphertext).decodeToString()   // throws AEADBadTagException if tampered
}

