fun unlock(activity: FragmentActivity, data: EncryptedData, onResult: (Result<String>) -> Unit) {
    val manager = BiometricManager.from(activity)
    if (manager.canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG) != BiometricManager.BIOMETRIC_SUCCESS) {
        onResult(Result.failure(BiometricUnavailable)); return
    }
    val cipher = try {
        Cipher.getInstance("AES/GCM/NoPadding").apply {
            init(Cipher.DECRYPT_MODE, getOrCreateKey(), GCMParameterSpec(128, data.iv))
        }
    } catch (e: KeyPermanentlyInvalidatedException) {
        deleteKey(); onResult(Result.failure(NeedsReEnrollment)); return   // new fingerprint added
    }
    BiometricPrompt(activity, ContextCompat.getMainExecutor(activity), object : BiometricPrompt.AuthenticationCallback() {
        override fun onAuthenticationSucceeded(r: BiometricPrompt.AuthenticationResult) {
            onResult(runCatching { r.cryptoObject!!.cipher!!.doFinal(data.ciphertext).decodeToString() })
        }
        override fun onAuthenticationError(code: Int, msg: CharSequence) = onResult(Result.failure(Cancelled(msg)))
    }).authenticate(
        BiometricPrompt.PromptInfo.Builder()
            .setTitle("Unlock your vault")
            .setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG)
            .setNegativeButtonText("Use password")
            .build(),
        BiometricPrompt.CryptoObject(cipher),
    )
}

