@Composable
fun HelpPage(url: String) {
    AndroidView(factory = { ctx ->
        WebView(ctx).apply {
            settings.javaScriptEnabled = true            // help pages need JS
            settings.allowFileAccess = false
            settings.allowContentAccess = false
            webViewClient = object : WebViewClient() {
                override fun shouldOverrideUrlLoading(view: WebView, req: WebResourceRequest): Boolean {
                    val ours = req.url.scheme == "https" && req.url.host == "help.shop.example"
                    if (!ours) CustomTabsIntent.Builder().build().launchUrl(ctx, req.url)   // external links outside
                    return !ours
                }
            }
            loadUrl(url.takeIf { Uri.parse(it).host == "help.shop.example" } ?: "about:blank")
        }
    })
}

